  "Aguiño y la Ría de Arousa: autenticidad marinera": { es: "Aguiño y la Ría de Arousa: autenticidad marinera", en: "Aguiño and the Ría de Arousa: seafaring authenticity", gl: "Aguiño e a Ría de Arousa: autenticidade mariñeira" },
  "Situado en el extremo sur de la península del Barbanza (Ribeira), Aguiño conserva el ritmo tranquilo de un pueblo marinero frente a las islas de Sálvora y Ons, con calas serenas y naturaleza abierta al Atlántico.": { es: "Situado en el extremo sur de la península del Barbanza (Ribeira), Aguiño conserva el ritmo tranquilo de un pueblo marinero frente a las islas de Sálvora y Ons, con calas serenas y naturaleza abierta al Atlántico.", en: "Located at the southern tip of the Barbanza peninsula (Ribeira), Aguiño keeps the calm rhythm of a fishing village facing the islands of Sálvora and Ons, with serene coves and open Atlantic nature.", gl: "Situado no extremo sur da península do Barbanza (Ribeira), Aguiño conserva o ritmo tranquilo dunha vila mariñeira fronte ás illas de Sálvora e Ons, con calas serenas e natureza aberta ao Atlántico." },
  "230 m² concebidos para vivir con amplitud": { es: "230 m² concebidos para vivir con amplitud", en: "230 m² designed for spacious living", gl: "230 m² concibidos para vivir con amplitude" },
  "Una planta ático con luz marina, 3 dormitorios (dos de ellos con baño en suite), 3 baños completos, despacho independiente y 50 m² de terraza abierta a la ría y a las islas de Sálvora y Ons.": { es: "Una planta ático con luz marina, 3 dormitorios (dos de ellos con baño en suite), 3 baños completos, despacho independiente y 50 m² de terraza abierta a la ría y a las islas de Sálvora y Ons.", en: "A penthouse floor with maritime light, 3 bedrooms (two with en-suite bathroom), 3 full bathrooms, an independent office and a 50 m² terrace open to the ría and the islands of Sálvora and Ons.", gl: "Unha planta ático con luz mariña, 3 dormitorios (dous deles con baño en suite), 3 baños completos, despacho independente e 50 m² de terraza aberta á ría e ás illas de Sálvora e Ons." },
  "Crónicas del Atlántico": { es: "Crónicas del Atlántico", en: "Chronicles of the Atlantic", gl: "Crónicas do Atlántico" },
  "Documentación rigurosa sobre el Parque Nacional, la cultura náutica, la oceanografía de la Ría de Arousa y la gastronomía de lonja.": { es: "Documentación rigurosa sobre el Parque Nacional, la cultura náutica, la oceanografía de la Ría de Arousa y la gastronomía de lonja.", en: "Rigorous documentation on the National Park, seafaring culture, the oceanography of the Ría de Arousa and fish market gastronomy.", gl: "Documentación rigorosa sobre o Parque Nacional, a cultura náutica, a oceanografía da Ría de Arousa e a gastronomía de lonxa." },
