  "Hola, me gustaría consultar disponibilidad para el Ático Illas Atlánticas.": { es: "Hola, me gustaría consultar disponibilidad para el Ático Illas Atlánticas.", en: "Hi, I'd like to check availability for the Illas Atlánticas penthouse.", gl: "Ola, gustaríame consultar a dispoñibilidade para o Ático Illas Atlánticas." },
  "Hola, me gustaría consultar disponibilidad directa para Illas Atlánticas Ático. Fechas: del {checkIn} al {checkOut} ({nights} noches). Ocupantes: {adults} adultos, {children} niños. ¿Tienen disponibilidad confirmada para estas fechas?": { es: "Hola, me gustaría consultar disponibilidad directa para Illas Atlánticas Ático. Fechas: del {checkIn} al {checkOut} ({nights} noches). Ocupantes: {adults} adultos, {children} niños. ¿Tienen disponibilidad confirmada para estas fechas?", en: "Hi, I'd like to check direct availability for Illas Atlánticas Ático. Dates: from {checkIn} to {checkOut} ({nights} nights). Guests: {adults} adults, {children} children. Do you have confirmed availability for these dates?", gl: "Ola, gustaríame consultar a dispoñibilidade directa para Illas Atlánticas Ático. Datas: do {checkIn} ao {checkOut} ({nights} noites). Ocupantes: {adults} adultos, {children} nenos. Tedes dispoñibilidade confirmada para estas datas?" },

  "consent.text": { es: "Medimos la audiencia sin cookies y sin datos personales. Si aceptas, añadimos Microsoft Clarity para ver cómo se usa la web y mejorarla.", en: "We measure our audience without cookies or personal data. If you accept, we add Microsoft Clarity to understand how the site is used and improve it.", gl: "Medimos a audiencia sen cookies e sen datos persoais. Se aceptas, engadimos Microsoft Clarity para ver como se usa a web e mellorala." },
  "consent.necessary": { es: "Solo lo necesario", en: "Essentials only", gl: "Só o necesario" },
  "consent.accept": { es: "Aceptar", en: "Accept", gl: "Aceptar" },
