  "consent.aria": { es: "Aviso de medición de audiencia", en: "Audience measurement notice", gl: "Aviso de medición de audiencia" },
  "legal.cookies.text": { es: "Esta web no utiliza cookies de publicidad ni de seguimiento comportamental. Para medir las visitas empleamos:", en: "This website does not use advertising or behavioural tracking cookies. To measure visits we use:", gl: "Esta web non utiliza cookies de publicidade nin de seguimento comportamental. Para medir as visitas empregamos:" },
  "legal.cookies.umami": { es: "Umami Cloud (umami.is, alojada en la UE): medición de audiencia sin cookies y sin datos personales, tratados de forma agregada.", en: "Umami Cloud (umami.is, hosted in the EU): audience measurement without cookies or personal data, processed in aggregate.", gl: "Umami Cloud (umami.is, aloxada na UE): medición de audiencia sen cookies e sen datos persoais, tratados de forma agregada." },
  "legal.cookies.baliza": { es: "Una baliza propia que registra únicamente la página visitada, la hora y una referencia irreversible de la conexión.", en: "Our own beacon that records only the page visited, the time and an irreversible reference of the connection.", gl: "Unha baliza propia que rexistra unicamente a páxina visitada, a hora e unha referencia irreversíbel da conexión." },
  "legal.cookies.clarity": { es: "Microsoft Clarity (Microsoft Corporation): grabaciones de sesión y mapas de calor para mejorar la web. Solo se activa si lo aceptas en el aviso de consentimiento y puedes retirarlo en cualquier momento. Las transferencias a EE. UU. se amparan en cláusulas contractuales tipo; las grabaciones se conservan 30 días.", en: "Microsoft Clarity (Microsoft Corporation): session recordings and heatmaps to improve the website. It is only activated if you accept it in the consent notice and you can withdraw it at any time. Transfers to the USA are covered by standard contractual clauses; recordings are kept for 30 days.", gl: "Microsoft Clarity (Microsoft Corporation): gravacións de sesión e mapas de calor para mellorar a web. Só se activa se o aceptas no aviso de consentimento e podes retiralo en calquera momento. As transferencias aos EE. UU. ampáranse en cláusulas contractuais tipo; as gravacións consérvanse 30 días." },
  "legal.cookies.salida": { es: "También se cargan los recursos técnicos imprescindibles: las tipografías de Google Fonts y el motor de reservas de Beds24 (cifrado HTTPS). Puedes desactivar las cookies de tu navegador en cualquier momento; la web seguirá funcionando.", en: "The essential technical resources are also loaded: Google Fonts typefaces and the Beds24 booking engine (HTTPS encryption). You can disable browser cookies at any time; the website will keep working.", gl: "Tamén se cargan os recursos técnicos imprescindibles: as tipografías de Google Fonts e o motor de reservas de Beds24 (cifrado HTTPS). Podes desactivar as cookies do navegador en calquera momento; a web seguirá funcionando." },

